<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>My Account – Barangay Doyong</title><link rel="stylesheet" href="{{ asset('css/dashboard.css') }}"><link rel="stylesheet" href="{{ asset('css/account-management.css') }}"></head>
<body class="account-reset"><main class="account-reset-card"><h1>My Account</h1><dl><dt>Name</dt><dd>{{ auth()->user()->name }}</dd><dt>Username</dt><dd>{{ auth()->user()->username ?: 'Not set' }}</dd><dt>Email</dt><dd>{{ auth()->user()->email }}</dd><dt>Contact number</dt><dd>{{ auth()->user()->contact_number ?: '—' }}</dd><dt>Role</dt><dd>{{ auth()->user()->role === 'admin' ? 'Administrator – Barangay Captain' : (auth()->user()->role === 'staff' ? 'Staff Member – Barangay Secretary' : 'Resident') }}</dd></dl><a href="{{ route('password.request') }}">Reset password by email</a><p><a href="{{ auth()->user()->role === 'admin' ? url('/admin/dashboard') : (auth()->user()->role === 'staff' ? route('staff.dashboard') : route('resident.dashboard')) }}">Back to dashboard</a></p></main></body></html>
